96	// runConfigureOnboarding is a seam for command tests. Bare interactive
97	// `entire configure` is the new end-to-end entry point; flag-based configure
98	// remains the non-interactive settings editor.
99	var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
100		return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
101	}
