103	func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
104		cmd.SilenceUsage = true
105		ctx := cmd.Context()
106		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
107	
108		repoRoot, err := paths.WorktreeRoot(ctx)
109		if err != nil {
110			fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
111			return NewSilentError(errors.New("not a git repository"))
112		}
113		owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
114		if err != nil {
115			return err
116		}
117	
118		profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
119		if err != nil {
120			return err
121		}
122	
123		reporter, err := deps.accessClient(ctx)
124		if err != nil {
125			return fmt.Errorf("connect to Entire: %w", err)
126		}
127		access, err := reporter.ReportEnable(ctx, cleanRemote)
128		if err != nil {
129			return fmt.Errorf("check repository access: %w", err)
130		}
131		if !access.Connected {
132			if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, opts.Yes, deps); err != nil {
133				return err
134			}
135		}
136	
137		client, err := deps.coreClient()
138		if err != nil {
139			return fmt.Errorf("connect to Entire control plane: %w", err)
140		}
141		placements, err := resolvePullablePlacements(ctx, client, owner, repo)
142		if err != nil {
143			return renderCoreError(err)
144		}
145		if len(placements) == 0 {
146			placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction, opts.Yes)
147			if err != nil {
148				return err
149			}
150		}
151		if len(placements) == 0 {
152			return errors.New("no usable mirror was selected")
153		}
154	
155		manageRegionsHint := ""
156		if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
157			manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
158				configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
159		}
160		initialChanges, err := configureGitChanges(ctx, repoRoot)
161		if err != nil {
162			return err
163		}
164		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
165		if branchErr != nil {
166			// Best-effort: local-only saves do not need a branch.
167			branch = ""
168		}
169		protected := false
170		protectionKnown := branch == ""
171		if branch != "" {
172			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
173				protected = detected
174				protectionKnown = true
175			}
176		}
177		// Non-interactive onboarding has no confirmation step. If GitHub protection
178		// cannot be checked (common when gh is unavailable in CI), fail closed and
179		// use the review branch rather than pushing directly to the checked-out
180		// branch. Interactive users can still explicitly choose a direct push when
181		// protection is known not to block it.
182		protected = configureEffectiveProtection(protected, protectionKnown, opts.Yes)
183		branchPushSafe := false
184		if branch != "" && len(initialChanges) == 0 {
185			branchPushSafe = configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)
186		}
187		chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
188			ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
189			branch, protected, branchPushSafe, opts.Yes,
190		)
191		if err != nil {
192			return err
193		}
194		if saveChoice == configureSaveCancel {
195			fmt.Fprintln(outW, "Configuration cancelled.")
196			return nil
197		}
198		if saveChoice == "" {
199			fmt.Fprintln(outW, "No configuration changes.")
200			return nil
201		}
202	
203		// Snapshot immediately before applying our changes. The form may have been
204		// open for an arbitrary amount of time, so the pre-form status is not a safe
205		// commit baseline: editor autosaves or another process may have changed files
206		// while the user was choosing options. Anything already dirty now is excluded
207		// from generated and disables automatic commit/push below.
208		beforeApply, err := configureGitChanges(ctx, repoRoot)
209		if err != nil {
210			return err
211		}
212		if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
213			(len(beforeApply) != 0 || !configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)) {
214			saveChoice = configureSaveLocal
215		}
216	
217		forgeRemote, err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen)
218		if err != nil {
219			return err
220		}
221	
222		if agentsChanged {
223			opts = configureOnboardingEnableOptions(opts)
224			if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
225				return err
226			}
227			// A local enabled:false override must not win over the newly written project
228			// configuration. setEnabledFlag updates the project and synchronizes an
229			// existing local override without replacing its other local-only fields.
230			if err := setEnabledFlag(ctx, true, true); err != nil {
231				return err
232			}
233		}
234	
235		after, err := configureGitChanges(ctx, repoRoot)
236		if err != nil {
237			return err
238		}
239		generated := newConfigureChanges(beforeApply, after)
240		if agentsChanged {
241			fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
242		}
243	
244		if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
245			if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
246				return err
247			}
248		} else if agentsChanged && len(generated) > 0 {
249			fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
250		}
251		fmt.Fprintln(outW, "✓ Configuration complete")
252		fmt.Fprintln(outW)
253		fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
254		fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
255		return nil
256	}
