258	func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
259		opts.Yes = true
260		opts.UseProjectSettings = true
261		opts.UseLocalSettings = false
262		opts.SuppressDoneMessage = true
263		opts.SuppressAdditionalSetup = true
264		// Logged-in onboarding does not ask a separate telemetry question. The
265		// documented default is applied without prompting; existing settings and
266		// ENTIRE_TELEMETRY_OPTOUT remain authoritative.
267		return opts
268	}
