330	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, nonInteractive bool, deps configureFlowDeps) error {
331		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
332		installURL := strings.TrimSpace(initial.InstallURL)
333		if installURL == "" {
334			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
335		}
336	
337		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
338		if adminErr == nil && !admin {
339			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
340			fmt.Fprintln(errW, "  Send them this link to continue:")
341			fmt.Fprintf(errW, "\n  %s\n", installURL)
342			return NewSilentError(errors.New("GitHub app installation required"))
343		}
344		if adminErr != nil {
345			switch {
346			case errors.Is(adminErr, errConfigureGHUnavailable):
347				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
348				fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
349			case errors.Is(adminErr, errConfigureGHUnauthenticated):
350				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
351				fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
352			default:
353				fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
354			}
355			fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
356			fmt.Fprintln(errW)
357		}
358	
359		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
360		fmt.Fprintf(outW, "  %s\n\n", installURL)
361		if nonInteractive {
362			return NewSilentError(errors.New("GitHub app installation required; install it with the URL above, then rerun 'entire configure --yes'"))
363		}
364		if err := deps.openURL(ctx, installURL); err != nil {
365			fmt.Fprintln(outW, "  Open the link above in your browser.")
366		}
367		stop := startSpinner(errW, "Waiting for installation")
368		stopped := false
369		defer func() {
370			if !stopped {
371				stop(false)
372			}
373		}()
374	
375		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
376		defer cancel()
377		ticker := time.NewTicker(configureAccessPollInterval)
378		defer ticker.Stop()
379		for {
380			select {
381			case <-waitCtx.Done():
382				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
383			case <-ticker.C:
384				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
385				if err == nil && access.Connected {
386					stop(true)
387					stopped = true
388					fmt.Fprintln(outW, "✓ Access granted")
389					return nil
390				}
391			}
392		}
393	}
