395	func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
396		runner := execRunner{}
397		if !ghAvailable(ctx, runner) {
398			return false, errConfigureGHUnavailable
399		}
400		if !ghAuthenticated(ctx, runner) {
401			return false, errConfigureGHUnauthenticated
402		}
403		out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
404		if err != nil {
405			return false, fmt.Errorf("check GitHub admin permission: %w", err)
406		}
407		admin, err := strconv.ParseBool(strings.TrimSpace(out))
408		if err != nil {
409			return false, fmt.Errorf("parse GitHub admin permission: %w", err)
410		}
411		return admin, nil
412	}
