545	func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
546		if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
547			switch {
548			case configureRadioSelectKey(keyMsg.String()):
549				field.commitHighlighted()
550				return field, configureWindowResize(field.window)
551			case configureNextKey(keyMsg.String()):
552				// Enter continues with the intentionally selected value. Merely moving
553				// the cursor does not change the radio selection.
554				return field, huh.NextField
555			}
556		}
557		if size, ok := msg.(tea.WindowSizeMsg); ok {
558			field.window = size
559		}
560		model, cmd := field.Select.Update(msg)
561		if updated, ok := model.(*huh.Select[string]); ok {
562			field.Select = updated
563		}
564		_, movedCursor := msg.(tea.KeyPressMsg)
565		field.preserveCommittedSelection(movedCursor)
566		return field, cmd
567	}
568	
569	func (field *configureUpstreamField) preserveCommittedSelection(movedCursor bool) {
570		if field.value == nil {
571			return
572		}
573		if movedCursor {
574			field.highlighted = *field.value
575		}
576		*field.value = field.committed
577	}
578	
579	func (field *configureUpstreamField) commitHighlighted() {
580		if field.value == nil {
581			return
582		}
583		field.committed = field.highlighted
584		*field.value = field.committed
585		if field.refresh != nil {
586			field.refresh()
587		}
