709	// promptConfigureUpstreamAndAgents presents upstream, agents, and the dynamic
710	// save action as one persistent form. Save is always visible, while its actions
711	// change based on whether the choices require only local state or a commit and
712	// push. Arrow keys stay within the active section; Enter advances, while
713	// shift+tab revisits the previous section.
714	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint, branch string, protected, cleanWorktree, nonInteractive bool) (coreapi.ResolvedPlacement, []agent.Agent, string, bool, error) {
715		currentHost := configureCurrentUpstream(ctx, repoRoot)
716		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
717		if len(placements) == 0 {
718			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no upstreams available")
719		}
720	
721		// configurePlacementOrder puts the configured upstream first, so it is also
722		// the initial selection. If this repo has no Entire upstream yet, it falls
723		// back to the jurisdiction-preferred placement.
724		selectedHost := placements[0].ClusterHost
725		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
726		for _, placement := range placements {
727			placementByHost[placement.ClusterHost] = placement
728		}
729		upstreamOptions := func() []huh.Option[string] {
730			return configureUpstreamOptions(placements, selectedHost, currentHost)
731		}
732	
733		external.DiscoverAndRegisterAlways(ctx)
734		preselected := configureAgentPreselection(ctx)
735		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
736		if len(agentOptions) == 0 {
737			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no agents with hook support available")
738		}
739		installedAgentNames := make([]string, 0)
740		for _, name := range GetAgentsWithHooksInstalled(ctx) {
741			installedAgentNames = append(installedAgentNames, string(name))
742		}
743		selectedAgentNames := make([]string, 0, len(preselected))
744		for _, option := range agentOptions {
745			if _, ok := preselected[types.AgentName(option.Value)]; ok {
746				selectedAgentNames = append(selectedAgentNames, option.Value)
747			}
748		}
749	
750		// huh's footer already documents navigation. Keep field descriptions for
751		// contextual information only, rather than repeating keyboard controls.
752		upstreamDescription := manageRegionsHint
753		upstreamControl := &configureUpstreamField{
754			value:       &selectedHost,
755			committed:   selectedHost,
756			highlighted: selectedHost,
757		}
758		upstreamControl.Select = huh.NewSelect[string]().
759			TitleFunc(func() string {
760				return configureQuestionTitle("Select your upstream", upstreamControl.focused)
761			}, &upstreamControl.focused).
762			Description(upstreamDescription).
763			Options(upstreamOptions()...).
764			Height(configureFieldHeight(len(placements), upstreamDescription)).
765			Value(&selectedHost)
766		upstreamControl.refresh = func() {
767			upstreamControl.Options(upstreamOptions()...)
768		}
769	
770		agentControl := newConfigureAgentControl(agentOptions, &selectedAgentNames, true)
771	
772		mirrorChanged := func() bool {
773			mirror, _ := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
774			return mirror
775		}
776		agentsChanged := func() bool {
777			_, agents := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
778			return agents
779		}
780		requiresPush := func() bool {
781			return agentsChanged() && cleanWorktree && branch != ""
782		}
783		hasChanges := func() bool {
784			return mirrorChanged() || agentsChanged()
785		}
786	
787		previousHasChanges := hasChanges()
788		saveChoice := defaultConfigureSaveChoice(previousHasChanges, requiresPush(), protected)
789		saveControl := &configureSaveField{}
790		saveOptions := func() []huh.Option[string] {
791			return configureSaveOptions(branch, protected, requiresPush(), hasChanges(), saveChoice)
792		}
793		saveControl.Select = huh.NewSelect[string]().
794			TitleFunc(func() string {
795				return configureQuestionTitle("Save configuration", saveControl.focused)
796			}, &saveControl.focused).
797			Description(configureSaveDescription(branch, protected, requiresPush(), hasChanges())).
798			Options(saveOptions()...).
799			Height(configureFieldHeight(len(saveOptions()), configureSaveDescription(branch, protected, requiresPush(), hasChanges()))).
800			Value(&saveChoice)
801		refreshSave := func() {
802			changed := hasChanges()
803			options := saveOptions()
804			if changed != previousHasChanges || !configureOptionsContain(options, saveChoice) {
805				saveChoice = defaultConfigureSaveChoice(changed, requiresPush(), protected)
806				options = saveOptions()
807			}
808			previousHasChanges = changed
809			description := configureSaveDescription(branch, protected, requiresPush(), changed)
810			saveControl.Select.
811				Description(description).
812				Height(configureFieldHeight(len(options), description)).
813				Options(options...)
814		}
815		upstreamControl.layoutChanged = refreshSave
816		agentControl.selectionChanged = refreshSave
817		agentControl.showSave = func() bool { return true }
818	
819		if nonInteractive {
820			chosen, ok := placementByHost[selectedHost]
821			if !ok {
822				return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("default upstream is no longer available")
823			}
824			selection, selectionErr := configureNonInteractiveAgentSelection(selectedAgentNames, agentOptions)
825			if selectionErr != nil {
826				return coreapi.ResolvedPlacement{}, nil, "", false, selectionErr
827			}
828			selectedAgentNames = selection
829			selectedAgents, err := configureSelectedAgents(selectedAgentNames)
830			if err != nil {
831				return coreapi.ResolvedPlacement{}, nil, "", false, err
832			}
833			return chosen, selectedAgents, configureNonInteractiveSaveChoice(hasChanges(), requiresPush(), protected), agentsChanged(), nil
834		}
835	
836		group := huh.NewGroup(upstreamControl, agentControl, saveControl)
837		form := newConfigureForm(group)
838		// Separate the form from the shell prompt or preceding onboarding status.
839		fmt.Fprintln(errW)
840		if err := form.RunWithContext(ctx); err != nil {
841			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
842				return coreapi.ResolvedPlacement{}, nil, "", false, cancelErr
843			}
844			return coreapi.ResolvedPlacement{}, nil, "", false, NewSilentError(errors.New("configure cancelled"))
845		}
846	
847		chosen, ok := placementByHost[selectedHost]
848		if !ok {
849			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("selected upstream is no longer available")
850		}
851		selectedAgents, err := configureSelectedAgents(selectedAgentNames)
852		if err != nil {
853			return coreapi.ResolvedPlacement{}, nil, "", false, err
854		}
855		if !hasChanges() && saveChoice != configureSaveCancel {
856			saveChoice = ""
857		}
858		return chosen, selectedAgents, saveChoice, agentsChanged(), nil
859	}
