959	func runConfigureAgentManagement(cmd *cobra.Command, opts EnableOptions) error {
960		cmd.SilenceUsage = true
961		ctx := cmd.Context()
962		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
963		repoRoot, err := paths.WorktreeRoot(ctx)
964		if err != nil {
965			return errors.New("not a git repository")
966		}
967		if !interactive.CanPromptInteractively() {
968			return runManageAgents(ctx, outW, opts, nil)
969		}
970	
971		initialChanges, err := configureGitChanges(ctx, repoRoot)
972		if err != nil {
973			return err
974		}
975		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
976		if branchErr != nil {
977			branch = ""
978		}
979		owner, repo, _, identityErr := configureRepoIdentity(ctx)
980		forgeRemote := ""
981		if identityErr == nil {
982			remotes, remotesErr := listGitRemotes(ctx, repoRoot)
983			if remotesErr != nil {
984				return remotesErr
985			}
986			forgeRemote, err = configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, "")
987			if err != nil {
988				return err
989			}
990		}
991		protected := false
992		if branch != "" && identityErr == nil {
993			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
994				protected = detected
995			}
996		}
997		pushSafe := branch != "" && forgeRemote != "" && len(initialChanges) == 0 &&
998			configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)
999		installedNames := GetAgentsWithHooksInstalled(ctx)
1000		selectedNames, saveChoice, changed, err := promptConfigureAgentsAndSave(ctx, errW, installedNames, branch, protected, pushSafe)
1001		if err != nil {
1002			return err
1003		}
1004		if saveChoice == configureSaveCancel {
1005			fmt.Fprintln(outW, "Agent configuration cancelled.")
1006			return nil
1007		}
1008		if !changed {
1009			fmt.Fprintln(outW, "No agent configuration changes.")
1010			return nil
1011		}
1012	
1013		beforeApply, err := configureGitChanges(ctx, repoRoot)
1014		if err != nil {
1015			return err
1016		}
1017		if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
1018			(len(beforeApply) != 0 || !configureBranchMatchesRemoteHead(ctx, repoRoot, forgeRemote, "refs/heads/"+branch)) {
1019			saveChoice = configureSaveLocal
1020		}
1021		if err := applyAgentChanges(ctx, outW, selectedNames, installedNames, opts); err != nil {
1022			return err
1023		}
1024		if saveChoice != configureSaveDirect && saveChoice != configureSaveNewBranch {
1025			return nil
1026		}
1027		afterApply, err := configureGitChanges(ctx, repoRoot)
1028		if err != nil {
1029			return err
1030		}
1031		generated := newConfigureChanges(beforeApply, afterApply)
1032		return configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, time.Now)
1033	}
