	raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
	if err != nil {
		return ""
	}
	info, err := gitremote.ParseURL(raw)
	if err != nil || info.Protocol != gitremote.ProtocolEntire {
